import java.sql.*;
import java.util.*;

import javax.sql.DataSource;

import org.h2.jdbcx.JdbcDataSource;

public class Main {
    public static void main(String[] args) throws SQLException {
        Scanner in = new Scanner(System.in);
        DataSource ds = Database.buat();
        try (Connection c = ds.getConnection();
             Statement st = c.createStatement()) {
            st.execute("CREATE TABLE IF NOT EXISTS kategori (id INT AUTO_INCREMENT PRIMARY KEY, nama VARCHAR(30) NOT NULL UNIQUE)");
            while (in.hasNextLine()) {
                String nama = in.nextLine().trim();
                try (PreparedStatement ps = c.prepareStatement("INSERT INTO kategori (nama) VALUES (?)")) {
                    ps.setString(1, nama);
                    ps.executeUpdate();
                    System.out.println("Kategori ditambah: " + nama);
                } catch (SQLException e) {
                    System.out.println("Kategori sudah ada: " + nama);
                }
            }
            try (ResultSet rs = st.executeQuery("SELECT COUNT(*) FROM kategori")) {
                rs.next();
                System.out.println("Total kategori: " + rs.getInt(1));
            }
        }
    }
}

